extern "C" double __cdecl sqrt(double x);
#pragma intrinsic(sqrt)

struct CRGBColour { unsigned char B, G, R, A; };
struct CCompositeBlendDesc {
    unsigned long TextureIndex;                     // +0x0
    long          BlendType;                        // +0x4 ECompositeBlendType
    CRGBColour    DiffuseColour;                    // +0x8
    CRGBColour    SpecularColour;                   // +0xC
};
template <class T> struct vector {
    T* _M_start;
    T* _M_finish;
    T* _M_end_of_storage;
    unsigned int size() const { return _M_finish - _M_start; }
    const T& operator[](unsigned int index) const { return _M_start[index]; }
};
struct CEngineTextureMorph {
    long                         OriginalTextureIndex;   // +0x0
    long                         MorphID;                // +0x4
    vector<CCompositeBlendDesc>  Blends;                 // +0x8
};

struct CEngineSurfaceCompositionManager_Methods : CEngineSurfaceCompositionManager {
    float CalcColourDifference(const CRGBColour& a, const CRGBColour& b) const;   // 0x00B2AF50
    bool IsNearlyIdentical(const CEngineTextureMorph& a, const CEngineTextureMorph& b, float tolerance) const;
};

#pragma auto_inline(off)
// Same-TU body of the helper (0x00B2AF50 sits directly above): seeing that it only reads lets VC keep both blend
// arrays' pointers and the count in registers across the calls. Not part of the graded symbol.
float CEngineSurfaceCompositionManager_Methods::CalcColourDifference(const CRGBColour& a, const CRGBColour& b) const
{
    float dr = (float)((long)a.R - (long)b.R);
    float dg = (float)((long)a.G - (long)b.G);
    float db = (float)((long)a.B - (long)b.B);
    float da = (float)((long)a.A - (long)b.A);
    return (float)sqrt(da * da + db * db + dg * dg + dr * dr);
}
#pragma auto_inline(on)

bool CEngineSurfaceCompositionManager_Methods::IsNearlyIdentical(const CEngineTextureMorph& a, const CEngineTextureMorph& b, float tolerance) const
{
    if (a.Blends.size() != b.Blends.size())
        return false;
    unsigned int count = a.Blends.size();
    for (unsigned int i = 0; i < count; ++i) {
        const CCompositeBlendDesc& blendA = a.Blends[i];
        const CCompositeBlendDesc& blendB = b.Blends[i];
        if (blendA.TextureIndex != blendB.TextureIndex)
            return false;
        if (CalcColourDifference(blendA.DiffuseColour, blendB.DiffuseColour) > tolerance)
            return false;
        if (CalcColourDifference(blendA.SpecularColour, blendB.SpecularColour) > tolerance)
            return false;
    }
    return true;
}

// ---- stubs and driver ----
static void SetBlend(CCompositeBlendDesc& d, unsigned long tex, long type, unsigned char r, unsigned char g, unsigned char b, unsigned char a,
                     unsigned char sr, unsigned char sg, unsigned char sb, unsigned char sa)
{
    d.TextureIndex = tex; d.BlendType = type;
    d.DiffuseColour.R = r; d.DiffuseColour.G = g; d.DiffuseColour.B = b; d.DiffuseColour.A = a;
    d.SpecularColour.R = sr; d.SpecularColour.G = sg; d.SpecularColour.B = sb; d.SpecularColour.A = sa;
}
static void SetMorph(CEngineTextureMorph& m, CCompositeBlendDesc* blends, unsigned int n)
{
    m.OriginalTextureIndex = 0; m.MorphID = 0;
    m.Blends._M_start = blends; m.Blends._M_finish = blends + n; m.Blends._M_end_of_storage = blends + n;
}
static char mgrStore[sizeof(CEngineSurfaceCompositionManager_Methods)];
int main()
{
    CEngineSurfaceCompositionManager_Methods* mgr = (CEngineSurfaceCompositionManager_Methods*)mgrStore;
    CCompositeBlendDesc a3[3], b3[3], c2[2];
    SetBlend(a3[0], 5, 0, 10, 20, 30, 40, 1, 2, 3, 4);
    SetBlend(a3[1], 6, 1, 100, 100, 100, 100, 0, 0, 0, 0);
    SetBlend(a3[2], 7, 2, 255, 0, 255, 0, 9, 9, 9, 9);
    for (int k = 0; k < 3; ++k) b3[k] = a3[k];
    b3[1].BlendType = 9;                                   // BlendType is not compared
    SetBlend(c2[0], 5, 0, 10, 20, 30, 40, 1, 2, 3, 4);
    SetBlend(c2[1], 6, 0, 100, 100, 100, 100, 0, 0, 0, 0);
    CEngineTextureMorph ma, mb, mc, me1, me2;
    SetMorph(ma, a3, 3); SetMorph(mb, b3, 3); SetMorph(mc, c2, 2); SetMorph(me1, 0, 0); SetMorph(me2, 0, 0);
    CHECK(mgr->IsNearlyIdentical(ma, mb, 0.0f));          // identical apart from BlendType
    CHECK(!mgr->IsNearlyIdentical(ma, mc, 100.0f));       // different counts
    CHECK(mgr->IsNearlyIdentical(me1, me2, 0.0f));        // both empty
    b3[2].TextureIndex = 8;
    CHECK(!mgr->IsNearlyIdentical(ma, mb, 1000.0f));      // texture differs
    b3[2].TextureIndex = 7;
    b3[1].DiffuseColour.R = 103; b3[1].DiffuseColour.G = 104;   // diffuse distance 5
    CHECK(mgr->IsNearlyIdentical(ma, mb, 5.0f));
    CHECK(!mgr->IsNearlyIdentical(ma, mb, 4.99f));
    CHECK(mgr->IsNearlyIdentical(mb, ma, 5.0f));
    b3[1].DiffuseColour.R = 100; b3[1].DiffuseColour.G = 100;
    b3[0].SpecularColour.A = 6;                            // specular distance 2
    CHECK(mgr->IsNearlyIdentical(ma, mb, 2.0f));
    CHECK(!mgr->IsNearlyIdentical(ma, mb, 1.5f));
    CHECK(!mgr->IsNearlyIdentical(mb, ma, 1.5f));
    char buf[64];
    _snprintf(buf, sizeof(buf), "%s", fails == 0 ? "00b2b050_TEST PASS" : "00b2b050_TEST FAIL");
    printf("%s\n", buf);
    return fails;
}
